"""Postseal descriptive strata; none are used to select updates or methods."""
from target90 import *
tasks=read(H90/'score_dev336_attempt001/ALL_TASK_ROWS_PRIVATE.json');supports=read(H90/'SUPPORT_ROLE_ROWS.json');updates=read(H90/'ALL_UPDATE_ROWS.json');held=read(H90/'HELDOUT_OBSERVATION_ROWS.json');out=[]
for label,mask in [('all',lambda r:True),('reference_available',lambda r:r['reference_roles']>0),('no_reference_available',lambda r:r['reference_roles']==0),('original_oracle_above25',lambda r:r['original_candidate_oracle_IoU']>.25),('original_oracle_at_most25',lambda r:r['original_candidate_oracle_IoU']<=.25)]:
 for pl in ['pooled','drone','quad']:
  ids={r['row'] for r in supports if mask(r) and (pl=='pooled' or r['platform']==pl)};ts=[t for t in tasks if t['row'] in ids]
  if not ts:continue
  for arm,ref in [('candidate_joint_frozen','frozen_bi'),('candidate_joint_tta1','candidate_joint_frozen'),('candidate_joint_tta1','candidate_joint_feature3'),('candidate_joint_tta1','candidate_joint_shuffle1'),('candidate_joint_tta1','no_ref_tta1')]:
   dv=np.array([t['IoU'][arm]-t['IoU'][ref] for t in ts]);out.append({'cohort':label,'platform':pl,'n':len(ts),'arm':arm,'reference':ref,'arm_mIoU_percent':float(np.mean([t['IoU'][arm] for t in ts])*100),'reference_mIoU_percent':float(np.mean([t['IoU'][ref] for t in ts])*100),'delta_pp':float(dv.mean()*100),'better_n':int((dv>1e-10).sum()),'worse_n':int((dv< -1e-10).sum()),'descriptive_only_not_acceptance_gate':True})
