by={t['row']:t for t in tasks};uu=[u for u in updates if u['mode']=='candidate_joint' and u['step']==1];diag={'state':'POSTSEAL_DESCRIPTIVE_ONLY','n':len(uu),'accepted':sum(u['accepted'] for u in uu),'conditional_improved':sum(u['after_conditional']<u['before_conditional']-1e-12 for u in uu),'physical_improved':sum(u['after_physical']<u['before_physical']-1e-12 for u in uu),'grounding_improved':sum(by[u['row']]['IoU']['candidate_joint_tta1']>by[u['row']]['IoU']['candidate_joint_frozen']+1e-10 for u in uu),'grounding_harmed':sum(by[u['row']]['IoU']['candidate_joint_tta1']<by[u['row']]['IoU']['candidate_joint_frozen']-1e-10 for u in uu),'heldout_mask_error_improved':sum(r['third_mask_conditional_error_after']<r['third_mask_conditional_error_before']-1e-12 for r in held),'heldout_mask_error_mean_before':float(np.mean([r['third_mask_conditional_error_before'] for r in held])),'heldout_mask_error_mean_after':float(np.mean([r['third_mask_conditional_error_after'] for r in held]))};dump(H90/'AUX_TASK_RELATION_DIAGNOSTIC.json',diag);print(diag)
